export function HiddenInput({
  name = "{{name}}",
  value = "{{value}}",
  purpose = "{{purpose}}",
  reveal = {{reveal}},
  accent = "{{accent}}",
}) {
  return (
    <form style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 320 }}>
      <p style={{ margin: "0 0 8px", fontSize: 13, color: "#24143099" }}>{purpose} carried invisibly with the form:</p>
      {reveal && (
        <div style={{ marginBottom: 10, padding: "8px 10px", border: `1.5px dashed ${accent}`, borderRadius: 8, background: "#FAF7F2", overflowX: "auto" }}>
          <code style={{ fontSize: 12, fontFamily: "ui-monospace, monospace", whiteSpace: "pre" }}>
            {`<input type="hidden" name="${name}" value="${value}">`}
          </code>
        </div>
      )}
      <input type="hidden" name={name} value={value} />
      <button type="submit" style={{ padding: "9px 16px", border: "none", borderRadius: 8, background: "#241430", color: "#FAF7F2", font: "inherit", fontWeight: 600, cursor: "pointer" }}>
        Submit form
      </button>
    </form>
  );
}
